        { id: "l95t5", type: "choice", q: "Во сколько раз 1 Мбайт больше 1 Кбайт?", answer: 1, options: ["1000", "1024", "8", "1024 * 1024"], explain: "1 Мбайт = 1024 Кбайта." }
